+/* validate indicator */
+static int
+pipe_validate_indicator(const guchar *header, const char *indicator) {
+    switch(*indicator) {
+        case SP_SUCCESS:
+            if (header[1] == 0x0 && header[2] == 0x0 && header[3] == 0x0) {
+                return SP_INDICATOR_OK;
+            } else {
+                return SP_INDICATOR_ERR;
+            }
+        case SP_FILE:
+        case SP_ERROR_MSG:
+        case SP_BAD_FILTER:
+        case SP_PACKET_COUNT:
+        case SP_DROPS:
+        case SP_TOOLBAR_CTRL:
+        case SP_QUIT:
+            return SP_INDICATOR_OK;
+    }
+    return SP_INDICATOR_ERR;
+}

